-- =============================================================================
-- RETIRO DE LOS DATOS DE DEMOSTRACIÓN · Pintu Clic
-- Generado por bd/script/datos-demo/generar.mjs. Deshace bd/sql/datos_demo_catalogo.sql:
--   · las órdenes DEMO-xxxx con sus líneas e historial,
--   · los productos de demostración (con sus imágenes, variantes y relaciones),
--   · los colores de demostración y las marcas y líneas que solo ellos usaban.
-- NO toca nada de lo que existía antes (seed, datos reales). Si alguno de estos productos ya se usó de verdad (está en un
-- carrito o en una cotización), la transacción falla con un error de llave foránea y no borra nada: se resuelve a mano.
-- =============================================================================
BEGIN;

DELETE FROM historial_estado_orden WHERE id_orden IN (SELECT id_orden FROM orden WHERE codigo_visible LIKE 'DEMO-%');
DELETE FROM linea_orden WHERE id_orden IN (SELECT id_orden FROM orden WHERE codigo_visible LIKE 'DEMO-%');
DELETE FROM orden WHERE codigo_visible LIKE 'DEMO-%';

-- Las imágenes de demostración (también las que se pusieron a los productos que ya existían), reconocidas por su contenido.
DELETE FROM imagen i USING producto p, marca m
WHERE p.id_producto = i.id_producto AND m.id_marca = p.id_marca
  AND (m.nombre, p.nombre, md5(i.datos)) IN (('Pintuco', 'Viniltex Advanced Mate', 'fdb4f41d5f0cfff2d19fb4b4e42972a9'), ('Pintuco', 'Viniltex Baños y Cocinas', '3fc90923d50fee6e36d06569628443a6'), ('Pintuco', 'Koraza Elastomérica', '3925e83a610fd4371bf5450b068b2ac7'), ('Pintuco', 'Pintulux Anticorrosivo Gris', '415b0f4db3a007014e7167e34f02c022'), ('Colorama', 'Colorama Vinilo Económico', 'cae2182e1106a42d90a10a2ac148d2d3'), ('Colorama', 'Colorama Esmalte Sintético', 'cae2182e1106a42d90a10a2ac148d2d3'), ('Colorama', 'Pintura de Demarcación y Pisos', '56b699079294c97f91c8b27686c5a8c0'), ('Colorama', 'Pintura para Tableros', 'fec325d5f2c1e21b0b9d0613b84c8b2d'), ('Colorama', 'Estuco Plástico Interiores', '667ca6ec88b00036d30927b400e5a0a5'), ('Colorama', 'Masilla Acrílica para Exteriores', 'cc210e325d1e05d17fa6dad5f8614361'), ('Colorama', 'Sellador Acrílico para Muros', '58cf558e407a9c40ececb3b9c3941612'), ('Colorama', 'Removedor de Pintura en Gel', '34f8da2a786a11659de2e69387d3b0cb'), ('Maderplus', 'Barniz Marino Brillante', '4adebea810148d6aa371203c59ca8071'), ('Maderplus', 'Laca Catalizada Brillante', '3dc608c4f609b864117c298c1f429e5b'), ('Maderplus', 'Tinte para Madera', '8e6c3ceddaf6a1a9840c443dc46a9ed1'), ('Impermax', 'Impermeabilizante Acrílico para Terrazas', 'e1628e1b12491acde49e08b1af521a21'), ('Impermax', 'Impermeabilizante para Muros', 'a3aa6da282a601ae27b55ea0c7e9c606'), ('Impermax', 'Silicona Sello de Juntas', 'cbef129da1bfd47ea2b1b39d4c1e81c0'), ('Colorama', 'Aerosol Multisuperficie', 'bedc68c9795bb0ac426044308df667a8'), ('Colorama', 'Aerosol Alta Temperatura', 'b2b449dfff02727209a1737a44081d45'), ('Goya', 'Brocha Profesional de 3 Pulgadas', 'e5c384725cd556989e876edddcf55ccf'), ('Goya', 'Brocha Angular para Cortes', '8a9e2cd20dcc2e471b2ad33be4034e86'), ('Goya', 'Rodillo de Felpa de 9 Pulgadas', '8741d00d2b9e6a8f88f298765943fc44'), ('Goya', 'Mini Rodillo de Espuma', 'bc893f5ba098504f8674b4c03f290d9d'), ('Goya', 'Bandeja para Rodillo', '823dbdf4a1dbc2dbf308d3ec73f41d10'), ('Goya', 'Extensión Telescópica para Rodillo', '503a8151db47cf54701c095cf78404e5'), ('Goya', 'Cinta de Enmascarar', '2ed06d0d3dff31f382ab128dc71c9ced'), ('Goya', 'Lija de Agua Grano 220', '6c0e422da7624839fb6432744028ff14'), ('Goya', 'Espátula de Acero de 3 Pulgadas', '8445441c68885f2e728ea717a5436a0f'), ('Pintuco', 'Viniltex Ultralavable', 'fdb4f41d5f0cfff2d19fb4b4e42972a9'), ('Pintuco', 'Koraza Sol & Lluvia', 'cfdcd85b08087d76b9810ea3d73529ce'), ('Pintuco', 'Pintulux 3 en 1', '3925e83a610fd4371bf5450b068b2ac7'), ('Pintuco', 'Esmalte ICO', '4a50e2e1b4edb29bd60f372937f6d103'), ('Pintuco', 'Barniz Transparente', '4adebea810148d6aa371203c59ca8071'), ('Goya', 'Brocha de cerda natural', '1ac81555c2d5ae7cd52d35ebc3554d30'));

DELETE FROM variante WHERE sku IN ('VIN-ADV-GAL', 'VIN-ADV-CUN', 'VIN-BYC-QT', 'VIN-BYC-GAL', 'KOR-ELA-GAL', 'KOR-ELA-CUN', 'PLX-ANT-QT', 'PLX-ANT-GAL', 'COL-VIN-GAL', 'COL-VIN-CUN', 'COL-ESM-QT', 'COL-ESM-GAL', 'COL-PIS-GAL', 'COL-PIS-CUN', 'COL-TAB-QT', 'COL-EST-GAL', 'COL-EST-CUN', 'COL-MAS-GAL', 'COL-SEL-GAL', 'COL-SEL-CUN', 'COL-REM-LT', 'MAD-BMA-QT', 'MAD-BMA-GAL', 'MAD-LAC-GAL', 'MAD-TIN-QT', 'MAD-TIN-GAL', 'IMP-TER-GAL', 'IMP-TER-CUN', 'IMP-MUR-GAL', 'IMP-SIL-300', 'COL-AER-400', 'COL-AAT-400', 'GOY-BRO-3', 'GOY-BRO-4', 'GOY-ANG-15', 'GOY-ROD-9', 'GOY-MIN-4', 'GOY-BAN-1', 'GOY-EXT-1', 'GOY-CIN-40', 'GOY-LIJ-220', 'GOY-ESP-3');

DELETE FROM producto p USING marca m
WHERE m.id_marca = p.id_marca AND (m.nombre, p.nombre) IN (('Pintuco', 'Viniltex Advanced Mate'), ('Pintuco', 'Viniltex Baños y Cocinas'), ('Pintuco', 'Koraza Elastomérica'), ('Pintuco', 'Pintulux Anticorrosivo Gris'), ('Colorama', 'Colorama Vinilo Económico'), ('Colorama', 'Colorama Esmalte Sintético'), ('Colorama', 'Pintura de Demarcación y Pisos'), ('Colorama', 'Pintura para Tableros'), ('Colorama', 'Estuco Plástico Interiores'), ('Colorama', 'Masilla Acrílica para Exteriores'), ('Colorama', 'Sellador Acrílico para Muros'), ('Colorama', 'Removedor de Pintura en Gel'), ('Maderplus', 'Barniz Marino Brillante'), ('Maderplus', 'Laca Catalizada Brillante'), ('Maderplus', 'Tinte para Madera'), ('Impermax', 'Impermeabilizante Acrílico para Terrazas'), ('Impermax', 'Impermeabilizante para Muros'), ('Impermax', 'Silicona Sello de Juntas'), ('Colorama', 'Aerosol Multisuperficie'), ('Colorama', 'Aerosol Alta Temperatura'), ('Goya', 'Brocha Profesional de 3 Pulgadas'), ('Goya', 'Brocha Angular para Cortes'), ('Goya', 'Rodillo de Felpa de 9 Pulgadas'), ('Goya', 'Mini Rodillo de Espuma'), ('Goya', 'Bandeja para Rodillo'), ('Goya', 'Extensión Telescópica para Rodillo'), ('Goya', 'Cinta de Enmascarar'), ('Goya', 'Lija de Agua Grano 220'), ('Goya', 'Espátula de Acero de 3 Pulgadas'))
  AND NOT EXISTS (SELECT 1 FROM variante v WHERE v.id_producto = p.id_producto);

DELETE FROM color c USING marca m
WHERE m.id_marca = c.id_marca AND (m.nombre, c.codigo) IN (('Pintuco', 'PIN-BLA-101'), ('Pintuco', 'PIN-BLA-102'), ('Pintuco', 'PIN-BLA-103'), ('Pintuco', 'PIN-BLA-104'), ('Pintuco', 'PIN-BLA-105'), ('Pintuco', 'PIN-BLA-106'), ('Pintuco', 'PIN-BLA-107'), ('Pintuco', 'PIN-BLA-108'), ('Pintuco', 'PIN-GRI-101'), ('Pintuco', 'PIN-GRI-102'), ('Pintuco', 'PIN-GRI-103'), ('Pintuco', 'PIN-GRI-104'), ('Pintuco', 'PIN-GRI-105'), ('Pintuco', 'PIN-GRI-106'), ('Pintuco', 'PIN-GRI-107'), ('Pintuco', 'PIN-GRI-108'), ('Pintuco', 'PIN-GRI-109'), ('Pintuco', 'PIN-AMA-101'), ('Pintuco', 'PIN-AMA-102'), ('Pintuco', 'PIN-AMA-103'), ('Pintuco', 'PIN-AMA-104'), ('Pintuco', 'PIN-AMA-105'), ('Pintuco', 'PIN-AMA-106'), ('Pintuco', 'PIN-AMA-107'), ('Pintuco', 'PIN-NAR-101'), ('Pintuco', 'PIN-NAR-102'), ('Pintuco', 'PIN-NAR-103'), ('Pintuco', 'PIN-NAR-104'), ('Pintuco', 'PIN-NAR-105'), ('Pintuco', 'PIN-NAR-106'), ('Pintuco', 'PIN-ROJ-101'), ('Pintuco', 'PIN-ROJ-102'), ('Pintuco', 'PIN-ROJ-103'), ('Pintuco', 'PIN-ROJ-104'), ('Pintuco', 'PIN-ROJ-105'), ('Pintuco', 'PIN-ROJ-106'), ('Pintuco', 'PIN-ROJ-107'), ('Pintuco', 'PIN-ROS-101'), ('Pintuco', 'PIN-ROS-102'), ('Pintuco', 'PIN-ROS-103'), ('Pintuco', 'PIN-ROS-104'), ('Pintuco', 'PIN-ROS-105'), ('Pintuco', 'PIN-ROS-106'), ('Pintuco', 'PIN-ROS-107'), ('Pintuco', 'PIN-ROS-108'), ('Pintuco', 'PIN-AZU-101'), ('Pintuco', 'PIN-AZU-102'), ('Pintuco', 'PIN-AZU-103'), ('Pintuco', 'PIN-AZU-104'), ('Pintuco', 'PIN-AZU-105'), ('Pintuco', 'PIN-AZU-106'), ('Pintuco', 'PIN-AZU-107'), ('Pintuco', 'PIN-AZU-108'), ('Pintuco', 'PIN-AZU-109'), ('Pintuco', 'PIN-VER-101'), ('Pintuco', 'PIN-VER-102'), ('Pintuco', 'PIN-VER-103'), ('Pintuco', 'PIN-VER-104'), ('Pintuco', 'PIN-VER-105'), ('Pintuco', 'PIN-VER-106'), ('Pintuco', 'PIN-VER-107'), ('Pintuco', 'PIN-VER-108'), ('Pintuco', 'PIN-TIE-101'), ('Pintuco', 'PIN-TIE-102'), ('Pintuco', 'PIN-TIE-103'), ('Pintuco', 'PIN-TIE-104'), ('Pintuco', 'PIN-TIE-105'), ('Pintuco', 'PIN-TIE-106'), ('Pintuco', 'PIN-TIE-107'), ('Pintuco', 'PIN-TIE-108'), ('Pintuco', 'PIN-TIE-109'), ('Pintuco', 'PIN-BLA-101-M'), ('Pintuco', 'PIN-BLA-103-M'), ('Pintuco', 'PIN-GRI-101-M'), ('Pintuco', 'PIN-GRI-104-M'), ('Pintuco', 'PIN-AMA-104-M'), ('Pintuco', 'PIN-NAR-101-M'), ('Pintuco', 'PIN-ROJ-104-M'), ('Pintuco', 'PIN-ROS-104-M'), ('Pintuco', 'PIN-AZU-102-M'), ('Pintuco', 'PIN-VER-107-M'), ('Pintuco', 'PIN-TIE-101-M'), ('Pintuco', 'PIN-TIE-109-M'), ('Colorama', 'COL-AER-NEG'), ('Colorama', 'COL-AER-BLA'), ('Colorama', 'COL-AER-ROJ'), ('Colorama', 'COL-AER-AZU'), ('Colorama', 'COL-AER-PLA'), ('Colorama', 'COL-AER-NMA'), ('Pintuco', 'PIN-ANT-GRI'), ('Pintuco', 'PIN-ANT-ROJ'), ('Colorama', 'COL-VIN-BLA'), ('Colorama', 'COL-ESM-BLA'), ('Colorama', 'COL-ESM-NEG'), ('Colorama', 'COL-ESM-ROJ'), ('Colorama', 'COL-ESM-AZU'), ('Colorama', 'COL-PIS-AMA'), ('Colorama', 'COL-TAB-VER'), ('Colorama', 'COL-TAB-NEG'), ('Maderplus', 'MAD-TIN-NOG'), ('Maderplus', 'MAD-TIN-CAO'), ('Maderplus', 'MAD-TIN-CED'), ('Maderplus', 'MAD-TIN-WEN'), ('Maderplus', 'MAD-TIN-ROB'), ('Maderplus', 'MAD-INC'), ('Impermax', 'IMP-TER'), ('Impermax', 'IMP-BLA'), ('Impermax', 'IMP-GRI'))
  AND NOT EXISTS (SELECT 1 FROM producto_color pc WHERE pc.id_color = c.id_color);

DELETE FROM linea l USING marca m
WHERE m.id_marca = l.id_marca AND m.nombre IN ('Colorama', 'Maderplus', 'Impermax')
  AND NOT EXISTS (SELECT 1 FROM producto p WHERE p.id_linea = l.id_linea);

DELETE FROM marca m
WHERE m.nombre IN ('Colorama', 'Maderplus', 'Impermax')
  AND NOT EXISTS (SELECT 1 FROM producto p WHERE p.id_marca = m.id_marca)
  AND NOT EXISTS (SELECT 1 FROM color c WHERE c.id_marca = m.id_marca)
  AND NOT EXISTS (SELECT 1 FROM linea l WHERE l.id_marca = m.id_marca);

COMMIT;
